#!/usr/bin/env python3
"""Seeded addressable solvable board generated by compact LEGAL macros.

Instead of:
    random board -> discover a gigantic physical sorting program

define the board constructively:
    canonical board --Q(seed)--> B

where Q(seed) is a small composition of legal blank programs:

1. route canonical blank from bottom-right to the common top-left anchor;
2. apply seeded HamiltonianRectangleCycle powers on many overlapping
   top-left-prefix rectangles, alternating row/column Hamiltonian orders;
3. route blank from the anchor to a seeded final coordinate.

Every primitive has an exact addressable positional map.  Therefore:

    B.value_at(position)
       = canonical_value(Q^{-1}(position))

and:
    B.position_of(tile)
       = Q(canonical_position(tile))

without materializing the board or replaying physical moves.

The exact solving program for B is simply Q^{-1}.  Solvability is therefore a
construction invariant, not a post-hoc parity condition.

This module is a candidate board family.  It does NOT claim statistical
uniformity over the sliding-puzzle component.  Distribution/mixing quality is
measured separately.
"""

from __future__ import annotations

from dataclasses import dataclass

from .blank_run import BlankRunTransform, forward_blank_run, inverse_blank_run
from .hamiltonian_rectangle_cycle import (
    HamiltonianRectangleCycle,
)
from .rectangle_cycle_macro import (
    Rectangle,
)
from .recursive_plan_grammar import (
    DIRS,
    Empty,
    PatternRepeat,
    PlanNode,
    Repeat,
    Run,
    Sequence,
    pattern_repeat,
    repeat,
    run,
    sequence,
)
from .seeded_lazy_sampler import (
    NodeRandom,
)


OPPOSITE={
    "U":"D",
    "D":"U",
    "L":"R",
    "R":"L",
}


def inverse_plan(
    node:PlanNode,
)->PlanNode:
    """Structural inverse of a legal UDLR grammar node."""
    if isinstance(
        node,
        Empty,
    ):
        return node
    if isinstance(
        node,
        Run,
    ):
        return Run(
            OPPOSITE[
                node.direction
            ],
            node.count,
        )
    if isinstance(
        node,
        PatternRepeat,
    ):
        inverse_pattern="".join(
            OPPOSITE[
                move
            ]
            for move in reversed(
                node.pattern
            )
        )
        return pattern_repeat(
            inverse_pattern,
            node.count,
        )
    if isinstance(
        node,
        Repeat,
    ):
        return repeat(
            inverse_plan(
                node.child
            ),
            node.count,
        )
    if isinstance(
        node,
        Sequence,
    ):
        return sequence(
            *(
                inverse_plan(
                    child
                )
                for child in reversed(
                    node.children
                )
            )
        )
    raise TypeError(
        type(
            node
        )
    )


@dataclass(frozen=True)
class CyclePrimitive:
    cycle:HamiltonianRectangleCycle

    @property
    def plan(self)->PlanNode:
        return self.cycle.plan

    def forward(
        self,
        rc:tuple[int,int],
    )->tuple[int,int]:
        return self.cycle.forward(
            rc
        )

    def inverse(
        self,
        rc:tuple[int,int],
    )->tuple[int,int]:
        return self.cycle.inverse(
            rc
        )


@dataclass(frozen=True)
class BlankRunPrimitive:
    transform:BlankRunTransform

    @property
    def plan(self)->PlanNode:
        return run(
            self.transform.direction,
            self.transform.count,
        )

    def forward(
        self,
        rc:tuple[int,int],
    )->tuple[int,int]:
        return forward_blank_run(
            self.transform,
            rc,
        )

    def inverse(
        self,
        rc:tuple[int,int],
    )->tuple[int,int]:
        return inverse_blank_run(
            self.transform,
            rc,
        )


class SeededLegalHamiltonianBoard:
    """One concrete board and compact legal solution determined by (side,seed)."""

    def __init__(
        self,
        side:int,
        seed:int,
        *,
        rounds:int=32,
        anchor_mode:str="prefix",
    ):
        if side<4:
            raise ValueError(
                "seeded Hamiltonian board requires side>=4"
            )
        if side%2:
            raise ValueError(
                "current seeded Hamiltonian board requires even side"
            )
        if seed<0:
            raise ValueError(
                "seed must be nonnegative"
            )
        if rounds<=0:
            raise ValueError(
                "rounds must be positive"
            )
        if anchor_mode not in (
            "prefix",
            "wandering",
            "multiscale",
            "ribbon",
            "orthogonal",
            "hybrid",
        ):
            raise ValueError(
                "anchor_mode must be prefix, wandering, multiscale, ribbon, "
                "orthogonal, or hybrid"
            )

        self.side=int(
            side
        )
        self.cells=self.side*self.side
        self.seed=int(
            seed
        )
        self.rounds=int(
            rounds
        )
        self.anchor_mode=anchor_mode

        primitives=[]

        # Canonical blank begins at bottom-right.  Route it to the common cycle
        # anchor.  Both runs are compact and have exact positional maps.
        blank=(
            self.side-1,
            self.side-1,
        )
        up=BlankRunTransform(
            blank,
            "U",
            self.side-1,
        )
        primitives.append(
            BlankRunPrimitive(
                up
            )
        )
        blank=up.end

        left=BlankRunTransform(
            blank,
            "L",
            self.side-1,
        )
        primitives.append(
            BlankRunPrimitive(
                left
            )
        )
        blank=left.end
        if blank!=(0,0):
            raise AssertionError(
                "seeded Hamiltonian setup missed common anchor"
            )

        def append_blank_route(
            target:tuple[int,int],
            *,
            horizontal_first:bool,
        )->None:
            nonlocal blank

            def add_axis(
                direction:str,
                count:int,
            )->None:
                nonlocal blank
                if count<=0:
                    return
                transform=BlankRunTransform(
                    blank,
                    direction,
                    count,
                )
                primitives.append(
                    BlankRunPrimitive(
                        transform
                    )
                )
                blank=transform.end

            dr=target[0]-blank[0]
            dc=target[1]-blank[1]
            vertical=(
                "D" if dr>0 else "U",
                abs(
                    dr
                ),
            )
            horizontal=(
                "R" if dc>0 else "L",
                abs(
                    dc
                ),
            )
            axes=(
                (horizontal,vertical)
                if horizontal_first
                else (vertical,horizontal)
            )
            for direction_count in axes:
                add_axis(
                    direction_count[0],
                    direction_count[1],
                )
            if blank!=target:
                raise AssertionError(
                    "seeded Hamiltonian blank route missed target anchor"
                )

        cycles=[]
        for round_index in range(
            self.rounds
        ):
            rng=NodeRandom(
                self.seed,
                (
                    0x48414D,
                    self.side,
                    self.rounds,
                    round_index,
                ),
            )

            mode=round_index%4
            preferred_orientation=None

            if self.anchor_mode=="hybrid":
                if round_index%2==0:
                    # Cheap global mixer.  Consecutive global rounds alternate
                    # row/column Hamiltonian order even though wandering rounds
                    # are interleaved between them.
                    height=self.side
                    width=self.side
                    preferred_orientation=(
                        "row"
                        if (
                            round_index//2
                        )%2==0
                        else "column"
                    )
                else:
                    # Regional symmetry breaker: retain the proven macroscopic
                    # wandering geometry, but only on half the rounds.
                    min_span=max(
                        4,
                        self.side//2,
                    )
                    height=(
                        min_span
                        +rng.randbelow(
                            self.side-min_span+1
                        )
                    )
                    width=(
                        min_span
                        +rng.randbelow(
                            self.side-min_span+1
                        )
                    )

                    want_column=bool(
                        (
                            round_index//2
                        )&1
                    )
                    if want_column:
                        if width%2:
                            width-=1
                        if width<2:
                            width=2
                        if (
                            height%2==0
                            and height>2
                        ):
                            height-=1
                    else:
                        if height%2:
                            height-=1
                        if height<2:
                            height=2

                    if height%2 and width%2:
                        width=(
                            width-1
                            if width>2
                            else width+1
                        )
            elif self.anchor_mode=="orthogonal":
                # Two different Hamiltonian (N-1)-cycles over the SAME full
                # board.  Both are legal and keep the blank at the common
                # top-left anchor; alternating their seeded powers composes
                # globally acting permutations without local windows.
                height=self.side
                width=self.side
                preferred_orientation=(
                    "row"
                    if round_index%2==0
                    else "column"
                )
            elif self.anchor_mode=="ribbon":
                phase=round_index%8
                if phase==0:
                    # Global reset/mixer: every cell participates.
                    height=self.side
                    width=self.side
                    ribbon_kind="full"
                elif phase in (
                    1,
                    3,
                    5,
                ):
                    # Horizontal shear: fine vertical scale, full horizontal
                    # reach.  Different phases cover side/4, side/8, side/16-32.
                    level={
                        1:2,
                        3:3,
                        5:4,
                    }[
                        phase
                    ]
                    low=max(
                        2,
                        self.side//(
                            1<<(
                                level+1
                            )
                        ),
                    )
                    high=max(
                        low,
                        self.side//(
                            1<<level
                        ),
                    )
                    height=(
                        low
                        +rng.randbelow(
                            high-low+1
                        )
                    )
                    if height%2:
                        height-=1
                    height=max(
                        2,
                        height,
                    )
                    width=self.side
                    ribbon_kind="horizontal"
                elif phase in (
                    2,
                    4,
                    6,
                ):
                    # Vertical shear: full vertical reach, fine horizontal
                    # scale.  This is the transpose partner of the above.
                    level={
                        2:2,
                        4:3,
                        6:4,
                    }[
                        phase
                    ]
                    low=max(
                        2,
                        self.side//(
                            1<<(
                                level+1
                            )
                        ),
                    )
                    high=max(
                        low,
                        self.side//(
                            1<<level
                        ),
                    )
                    width=(
                        low
                        +rng.randbelow(
                            high-low+1
                        )
                    )
                    if width%2:
                        width-=1
                    width=max(
                        2,
                        width,
                    )
                    height=self.side
                    ribbon_kind="vertical"
                else:
                    # One large 2-D wandering rectangle per epoch keeps the
                    # family from degenerating into only axis-separable shears.
                    min_span=max(
                        4,
                        self.side//2,
                    )
                    height=(
                        min_span
                        +rng.randbelow(
                            self.side-min_span+1
                        )
                    )
                    width=(
                        min_span
                        +rng.randbelow(
                            self.side-min_span+1
                        )
                    )
                    if height%2:
                        height-=1
                    height=max(
                        2,
                        height,
                    )
                    ribbon_kind="large2d"
            elif self.anchor_mode=="multiscale":
                phase=round_index%8
                if phase==0:
                    # Keep a periodic whole-board mixer, but spend most rounds
                    # on smaller scales where M9g2 found residual structure.
                    height=self.side
                    width=self.side
                else:
                    levels=(
                        1,
                        2,
                        3,
                        4,
                        5,
                    )
                    epoch=round_index//8
                    h_level=levels[
                        (
                            epoch
                            +phase-1
                        )%len(
                            levels
                        )
                    ]
                    w_level=levels[
                        (
                            epoch
                            +2*(
                                phase-1
                            )
                            +1
                        )%len(
                            levels
                        )
                    ]

                    def span_for(
                        level:int,
                    )->int:
                        low=max(
                            4,
                            self.side//(
                                1<<level
                            ),
                        )
                        high=min(
                            self.side,
                            max(
                                low,
                                self.side//(
                                    1<<max(
                                        0,
                                        level-1,
                                    )
                                ),
                            ),
                        )
                        return (
                            low
                            +rng.randbelow(
                                high-low+1
                            )
                        )

                    height=span_for(
                        h_level
                    )
                    width=span_for(
                        w_level
                    )

                    want_column=bool(
                        phase&1
                    )
                    if want_column:
                        if width%2:
                            width-=1
                        if width<2:
                            width=2
                        if (
                            height%2==0
                            and height>2
                        ):
                            height-=1
                    else:
                        if height%2:
                            height-=1
                        if height<2:
                            height=2

                    if height%2 and width%2:
                        width=(
                            width-1
                            if width>2
                            else width+1
                        )
            elif mode==0:
                # A periodic full-board cycle gives every cell global exposure.
                height=self.side
                width=self.side
            elif (
                self.anchor_mode=="prefix"
                and mode==1
            ):
                # Original M9g0 transpose round.
                height=self.side-1
                width=self.side
            else:
                # Original wandering family: every non-full rectangle spans at
                # least half the board.  Kept bit-for-bit for frozen M9g0/M9g2
                # comparisons.
                min_span=max(
                    4,
                    self.side//2,
                )
                height=(
                    min_span
                    +rng.randbelow(
                        self.side-min_span+1
                    )
                )
                width=(
                    min_span
                    +rng.randbelow(
                        self.side-min_span+1
                    )
                )

                want_column=(
                    mode in (
                        1,
                        3,
                    )
                )
                if want_column:
                    if width%2:
                        width-=1
                    if width<2:
                        width=2
                    if (
                        height%2==0
                        and height>2
                    ):
                        height-=1
                else:
                    if height%2:
                        height-=1
                    if height<2:
                        height=2

                if height%2 and width%2:
                    width=(
                        width-1
                        if width>2
                        else width+1
                    )

            if self.anchor_mode in (
                "wandering",
                "multiscale",
                "ribbon",
                "orthogonal",
                "hybrid",
            ):
                r0=(
                    0
                    if height==self.side
                    else rng.randbelow(
                        self.side-height+1
                    )
                )
                c0=(
                    0
                    if width==self.side
                    else rng.randbelow(
                        self.side-width+1
                    )
                )
            else:
                r0=0
                c0=0

            rect=Rectangle(
                r0,
                r0+height,
                c0,
                c0+width,
            )

            append_blank_route(
                rect.anchor,
                horizontal_first=bool(
                    round_index&1
                ),
            )

            ring=(
                rect.height*rect.width
                -1
            )
            if ring<=1:
                raise AssertionError(
                    "seeded Hamiltonian round has degenerate ring"
                )
            count=(
                1
                +rng.randbelow(
                    ring-1
                )
            )
            cycle=HamiltonianRectangleCycle(
                rect,
                count,
                preferred_orientation=preferred_orientation,
            )
            primitive=CyclePrimitive(
                cycle
            )
            primitives.append(
                primitive
            )
            cycles.append(
                cycle
            )
            # Every Hamiltonian cycle returns its blank to rect.anchor.
            blank=rect.anchor

        # Seed the observable blank coordinate too.  This route is part of Q,
        # hence also part of the exact addressable board permutation.
        final_rng=NodeRandom(
            self.seed,
            (
                0x424C414E4B,
                self.side,
                self.rounds,
            ),
        )
        final_blank=(
            final_rng.randbelow(
                self.side
            ),
            final_rng.randbelow(
                self.side
            ),
        )

        append_blank_route(
            final_blank,
            horizontal_first=False,
        )

        self.primitives=tuple(
            primitives
        )
        self.cycles=tuple(
            cycles
        )
        self.final_blank=final_blank
        self.scramble_plan=sequence(
            *(
                primitive.plan
                for primitive in self.primitives
            )
        )
        self.solution_plan=inverse_plan(
            self.scramble_plan
        )

    @staticmethod
    def _canonical_value(
        position:int,
        cells:int,
    )->int:
        return (
            0
            if position==cells-1
            else position+1
        )

    @staticmethod
    def _canonical_position(
        value:int,
        cells:int,
    )->int:
        return (
            cells-1
            if value==0
            else value-1
        )

    def forward_position(
        self,
        rc:tuple[int,int],
    )->tuple[int,int]:
        current=rc
        for primitive in self.primitives:
            current=primitive.forward(
                current
            )
        return current

    def inverse_position(
        self,
        rc:tuple[int,int],
    )->tuple[int,int]:
        current=rc
        for primitive in reversed(
            self.primitives
        ):
            current=primitive.inverse(
                current
            )
        return current

    def inverse_position_after_solution_primitives(
        self,
        rc:tuple[int,int],
        solved_primitives:int,
    )->tuple[int,int]:
        """Map a CURRENT position back to canonical after exact macro replay.

        The initial board is P0..P(n-1)(canonical).  After k complete
        primitives of Q^-1 have executed, the state is exactly
        P0..P(n-k-1)(canonical).  Therefore a tile lookup only needs the
        inverse of that remaining prefix; no physical moves are expanded.
        """
        total=len(
            self.primitives
        )
        if not 0<=solved_primitives<=total:
            raise IndexError(
                solved_primitives
            )
        remaining=(
            total
            -solved_primitives
        )
        current=rc
        for primitive in reversed(
            self.primitives[
                :remaining
            ]
        ):
            current=primitive.inverse(
                current
            )
        return current

    def tile_at_solution_primitive_step(
        self,
        row:int,
        col:int,
        solved_primitives:int,
    )->int:
        if not (
            0<=row<self.side
            and 0<=col<self.side
        ):
            raise IndexError(
                (
                    row,
                    col,
                )
            )
        source=self.inverse_position_after_solution_primitives(
            (
                row,
                col,
            ),
            solved_primitives,
        )
        position=(
            source[
                0
            ]*self.side
            +source[
                1
            ]
        )
        return self._canonical_value(
            position,
            self.cells,
        )

    def tile_at(
        self,
        row:int,
        col:int,
    )->int:
        if not (
            0<=row<self.side
            and 0<=col<self.side
        ):
            raise IndexError(
                (
                    row,
                    col,
                )
            )
        source=self.inverse_position(
            (
                row,
                col,
            )
        )
        position=(
            source[
                0
            ]*self.side
            +source[
                1
            ]
        )
        return self._canonical_value(
            position,
            self.cells,
        )

    def value_at(
        self,
        position:int,
    )->int:
        if not 0<=position<self.cells:
            raise IndexError(
                position
            )
        row,col=divmod(
            position,
            self.side,
        )
        return self.tile_at(
            row,
            col,
        )

    def position_of_tile(
        self,
        value:int,
    )->tuple[int,int]:
        if not 0<=value<self.cells:
            raise IndexError(
                value
            )
        position=self._canonical_position(
            value,
            self.cells,
        )
        rc=divmod(
            position,
            self.side,
        )
        return self.forward_position(
            rc
        )

    def materialize_row_major(
        self,
    )->list[int]:
        return [
            self.tile_at(
                row,
                col,
            )
            for row in range(
                self.side
            )
            for col in range(
                self.side
            )
        ]

    def diagnostics(
        self,
    )->dict[str,object]:
        return {
            "side":self.side,
            "cells":self.cells,
            "seed":self.seed,
            "rounds":self.rounds,
            "anchorMode":self.anchor_mode,
            "primitiveCount":len(
                self.primitives
            ),
            "cycleCount":len(
                self.cycles
            ),
            "finalBlank":list(
                self.final_blank
            ),
            "scramblePhysicalLength":self.scramble_plan.physical_length,
            "solutionPhysicalLength":self.solution_plan.physical_length,
            "cycles":[
                cycle.diagnostics()
                for cycle in self.cycles
            ],
        }
